export function signboardPlan(text, { at, face, mode = "wall", width, height = 2, wood = "spruce", board, bracket, chains = true, look = LOOK_NONE, dataVersion = 4189 } = {}) {
  const F = frame(face, at), writes = [], notes = [], T = String(text ?? "").trim();
  const planks = board || `${wood}_planks`, fence = bracket || `${wood}_fence`, ink = (lumOf(planks) ?? 100) < 90 ? "white" : "black";
  const signAt = (p, facing, lines, support) => writes.push(block(p, `${wood}_wall_sign`, "rail", { state: { facing, waterlogged: "false" }, nbt: signNbt(lines, { dataVersion, color: ink }), support }));
  const chain = dataVersion >= 4554 ? "iron_chain" : "chain";
