export function commitGrid(g, plan, { avoid } = {}) {
  const look = lookGrid(g), done = new Set(), notes = [...(plan.notes || [])];
  let cells = 0, skipped = 0, outside = 0;
  const avoided = (p) => (typeof avoid === "function" ? avoid(p) : avoid?.has(K(p)));
  for (const w of plan.writes) {
    if (!g.inBounds(...w.p)) { outside++; skipped++; continue; }
    if (avoided(w.p) || (w.support && look.air(w.support))) { skipped++; continue; }
    const cur = look.block(w.p), mine = done.has(K(w.p));
    const ok = { air: () => AIRY(cur) || mine, soft: () => AIRY(cur) || mine, rail: () => AIRY(cur), inplace: () => FULL(cur) || mine, recolor: () => FULL(cur) || mine,
      opening: () => GLAZED(cur) || mine, clear: () => FULL(cur) || GLAZED(cur) }[w.kind] ?? (() => true);
    if (!ok()) { skipped++; continue; }
    const [id, state] = resolve(w);
    const before = g.refused?.length ?? 0;
    g.set(...w.p, id, state, w.nbt);
    if ((g.refused?.length ?? 0) > before) { skipped++; continue; }
    done.add(K(w.p)); cells++;
  }
  if (outside) notes.push(`${outside} writes fell outside the grid (grow it: g.resize)`);
  return { cells, skipped, notes, ...(plan.info ? { info: plan.info } : {}) };
}

/** The plan's writes as g.set argument lists, unchecked. */
export const tuples = (plan) => plan.writes.map((w) => { const [id, st] = resolve(w); return [...w.p, id, st, w.nbt]; });

/** A deterministic hash in [0, 1). */
export const hash3 = (a, b, s = 0) => { let h = (a * 73856093) ^ (b * 19349663) ^ Math.imul(s | 0, 83492791); h = Math.imul(h ^ (h >>> 13), 1274126177); return ((h ^ (h >>> 16)) >>> 0) / 4294967296; };

/** Fence / wall / pane connection state for a straight run along one horizontal axis (dirs that connect). */
export function connState(block, dirs) {
  const b = strip(block), st = {};
  if (/_wall$/.test(b)) { for (const d of Object.keys(DIR)) st[d] = dirs.includes(d) ? "low" : "none"; st.up = dirs.length === 2 && OPP[dirs[0]] === dirs[1] ? "false" : "true"; }
  else for (const d of Object.keys(DIR)) st[d] = String(dirs.includes(d));
  st.waterlogged = "false";
  return st;
}
export const lanternState = (hanging) => ({ hanging: String(!!hanging), waterlogged: "false" });
export const trapdoorState = (facing, open = true, half = "bottom") => ({ facing, half, open: String(open), powered: "false", waterlogged: "false" });
