export const hash3 = (a, b, s = 0) => { let h = (a * 73856093) ^ (b * 19349663) ^ Math.imul(s | 0, 83492791); h = Math.imul(h ^ (h >>> 13), 1274126177); return ((h ^ (h >>> 16)) >>> 0) / 4294967296; };

/** Fence / wall / pane connection state for a straight run along one horizontal axis (dirs that connect). */
export function connState(block, dirs) {
  const b = strip(block), st = {};
  if (/_wall$/.test(b)) { for (const d of Object.keys(DIR)) st[d] = dirs.includes(d) ? "low" : "none"; st.up = dirs.length === 2 && OPP[dirs[0]] === dirs[1] ? "false" : "true"; }
